import{_ as o,a8 as t,o as n,c as d,ah as r,K as s}from"./chunks/framework.DJSDiqQ2.js";import"./chunks/theme.DK19TWbx.js";const u=JSON.parse('{"title":"Agent 记忆系统","description":"为任意项目自动创建和管理跨 AI 工具的长期记忆系统（.memory/ 目录）。当用户要求初始化项目记忆、设置 Agent 记忆、给项目增加长期记忆能力、或者在新项目中首次需要跨会话保留上下文时使用。支持 WorkBuddy/Cursor/Codex/Claude Code 等所有 AI 编码工具。","frontmatter":{"name":"agent-memory","description":"为任意项目自动创建和管理跨 AI 工具的长期记忆系统（.memory/ 目录）。当用户要求初始化项目记忆、设置 Agent 记忆、给项目增加长期记忆能力、或者在新项目中首次需要跨会话保留上下文时使用。支持 WorkBuddy/Cursor/Codex/Claude Code 等所有 AI 编码工具。","description_zh":"项目级 Agent 长期记忆系统 — 自动创建 .memory/ 目录结构，让不同 AI 编码工具之间共享项目上下文、技术决策和开发进度。","version":"1.4.0","agent_created":true},"headers":[],"relativePath":"vault/_Skills/agent-memory/SKILL.md","filePath":"vault/_Skills/agent-memory/SKILL.md","lastUpdated":1784383933000}'),l={name:"vault/_Skills/agent-memory/SKILL.md"};function h(c,i,p,k,g,m){const a=t("NolebaseGitContributors"),e=t("NolebaseGitChangelog");return n(),d("div",null,[i[0]||(i[0]=r(`<h1 id="agent-记忆系统" tabindex="-1">Agent 记忆系统 <a class="header-anchor" href="#agent-记忆系统" aria-label="Permalink to “Agent 记忆系统”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>为任意项目创建 <code>.memory/</code> 目录结构，实现跨 AI 工具、跨会话的项目长期记忆。不需要任何外部依赖，纯 Markdown 文件系统。</p><p><strong>核心理念</strong>：不保存完整聊天历史，而是将有用的上下文（决策、约定、进度、偏好）序列化为简洁、可检索的 Markdown 文件。<strong>.memory/AGENTS.md 是唯一入口</strong>——AI 只需读这一个文件，就知道项目的一切和会话工作流。</p><p><strong>支持工具</strong>：WorkBuddy、Cursor、Codex、Claude Code、GitHub Copilot 等任何能读写文件的 AI 编码助手。</p><hr><h2 id="初始化项目记忆" tabindex="-1">初始化项目记忆 <a class="header-anchor" href="#初始化项目记忆" aria-label="Permalink to “初始化项目记忆”">​</a></h2><p>有两种初始化方式：</p><h3 id="方式一-运行-init-脚本-优先" tabindex="-1">方式一：运行 init 脚本（优先） <a class="header-anchor" href="#方式一-运行-init-脚本-优先" aria-label="Permalink to “方式一：运行 init 脚本（优先）”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> scripts/init_memory.py</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> [项目根目录] [--desc </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;项目描述&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] [--stack </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;技术栈,逗号分隔&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">]</span></span></code></pre></div><p>示例：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> scripts/init_memory.py</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> ./my-project</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> --desc</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> &quot;宠物医院预约系统&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> --stack</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> &quot;Python,FastAPI,SQLite,Vue3&quot;</span></span></code></pre></div><p>脚本会：</p><ol><li>在项目根目录创建 <code>.memory/</code> 目录结构</li><li>复制所有模板文件并自动填充项目名称</li><li>如果传了 <code>--desc</code>，将项目描述写入 AGENTS.md（替换占位提示）</li><li>如果传了 <code>--stack</code>，将技术栈填入 AGENTS.md 技术栈表格</li><li>自动检测 AI 工具配置文件（<code>.cursorrules</code> / <code>CLAUDE.md</code> 等），不存在则创建引用行，存在但未引用则警告</li><li>不覆盖已有的 <code>.memory/</code>（安全保护）</li></ol><h3 id="方式二-手动复制模板" tabindex="-1">方式二：手动复制模板 <a class="header-anchor" href="#方式二-手动复制模板" aria-label="Permalink to “方式二：手动复制模板”">​</a></h3><p>从 <code>assets/templates/</code> 复制以下文件到项目 <code>.memory/</code> 目录：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>.memory/</span></span>
<span class="line"><span>├── AGENTS.md                 # 唯一入口（项目身份 + 工作流指令，每次会话必读）</span></span>
<span class="line"><span>├── context/</span></span>
<span class="line"><span>│   └── decisions.md          # 技术决策日志</span></span>
<span class="line"><span>└── working/</span></span>
<span class="line"><span>    ├── todo.md               # 进度跟踪</span></span>
<span class="line"><span>    └── plan.md               # 实施计划（可选）</span></span></code></pre></div><hr><h2 id="工具适配指南" tabindex="-1">工具适配指南 <a class="header-anchor" href="#工具适配指南" aria-label="Permalink to “工具适配指南”">​</a></h2><blockquote><p><strong>关键前提</strong>：AI 工具不会自动读取 <code>.memory/</code>。你需要在工具的配置文件中加一行引用。</p></blockquote><p>不同工具引用 <code>.memory/</code> 的方式——<strong>只需一行，让 AI 在每次会话自动读取 AGENTS.md</strong>：</p><table tabindex="0"><thead><tr><th>工具</th><th>配置位置</th><th>写入内容</th></tr></thead><tbody><tr><td><strong>Cursor</strong></td><td>项目根 <code>.cursorrules</code></td><td><code>每次会话开始时，先读取 .memory/AGENTS.md。</code></td></tr><tr><td><strong>Claude Code</strong></td><td>项目根 <code>CLAUDE.md</code></td><td>同上</td></tr><tr><td><strong>WorkBuddy</strong></td><td>项目根 <code>AGENT.md</code> 或 <code>.workbuddy/rules/</code></td><td>同上</td></tr><tr><td><strong>Codex/Windsurf</strong></td><td>项目根 <code>.windsurfrules</code></td><td>同上</td></tr><tr><td><strong>Copilot</strong></td><td><code>.github/copilot-instructions.md</code></td><td>同上</td></tr></tbody></table><p>AGENTS.md 已内置完整的启动/收尾工作流和决策记录格式，AI 读完后自然知道该做什么——<strong>零复制粘贴</strong>。</p><hr><h2 id="日常工作流" tabindex="-1">日常工作流 <a class="header-anchor" href="#日常工作流" aria-label="Permalink to “日常工作流”">​</a></h2><h3 id="新会话启动时-—-分层读取" tabindex="-1">新会话启动时 — 分层读取 <a class="header-anchor" href="#新会话启动时-—-分层读取" aria-label="Permalink to “新会话启动时 — 分层读取”">​</a></h3><p>不要无脑读全部 5 个文件。按任务性质分层：</p><table tabindex="0"><thead><tr><th>层级</th><th>文件</th><th>触发条件</th></tr></thead><tbody><tr><td><strong>必须读</strong></td><td><code>.memory/AGENTS.md</code></td><td>所有任务（项目身份、技术栈、关键约定）</td></tr><tr><td><strong>继续开发时读</strong></td><td><code>.memory/working/todo.md</code>、<code>.memory/working/plan.md</code></td><td>继续昨天的开发、修复 bug、实现新功能</td></tr><tr><td><strong>牵涉架构时查</strong></td><td><code>.memory/context/decisions.md</code></td><td>做技术选型、修改核心模块、重构时搜索相关决策（不全量加载）</td></tr></tbody></table><h3 id="会话结束时-—-记忆收尾-必做" tabindex="-1">会话结束时 — 记忆收尾（必做） <a class="header-anchor" href="#会话结束时-—-记忆收尾-必做" aria-label="Permalink to “会话结束时 — 记忆收尾（必做）”">​</a></h3><ol><li><strong>更新进度</strong>：编辑 <code>.memory/working/todo.md</code><ul><li>完成的阶段/任务 → 打勾 <code>[x]</code></li><li>更新「当前位置」描述</li></ul></li><li><strong>记录决策</strong>：如果有新的技术决策 → 追加到 <code>.memory/context/decisions.md</code><ul><li>格式：<code>[日期] [分类] 决策项 → 选定方案 | 原因 | via:来源</code></li></ul></li><li><strong>同步计划</strong>：如果 <code>plan.md</code> 存在 → 更新计划状态</li></ol><hr><h2 id="记忆文件规范" tabindex="-1">记忆文件规范 <a class="header-anchor" href="#记忆文件规范" aria-label="Permalink to “记忆文件规范”">​</a></h2><h3 id="agents-md-—-唯一入口" tabindex="-1">AGENTS.md — 唯一入口 <a class="header-anchor" href="#agents-md-—-唯一入口" aria-label="Permalink to “AGENTS.md — 唯一入口”">​</a></h3><p><strong>包含章节</strong>：</p><ul><li>项目概述（一两句话）</li><li>技术栈（表格，首次技术选型后填写）</li><li>关键约定（开发中逐步添加）</li><li>记忆文件索引（含&quot;何时读&quot;指引）</li><li>会话工作流（启动步骤 + 收尾步骤 + 决策记录格式）</li></ul><p><strong>初始状态</strong>：各章节只留引导提示（斜体），在开发过程中由 AI 或用户增量填充。</p><p><strong>设计意图</strong>：AI 只需读这一个文件，就能知道项目身份、记忆文件在哪、会话如何启动和收尾。无需复制粘贴任何内容。</p><h3 id="context-decisions-md-—-技术决策日志" tabindex="-1">context/decisions.md — 技术决策日志 <a class="header-anchor" href="#context-decisions-md-—-技术决策日志" aria-label="Permalink to “context/decisions.md — 技术决策日志”">​</a></h3><p><strong>写入时机</strong>：任何影响架构、技术栈或设计模式的选择。</p><p><strong>格式</strong>：<code>[YYYY-MM-DD] [分类] 决策项 → 选定方案 | 原因 | via:来源</code></p><p><strong>分类标签</strong>：</p><ul><li><code>[架构]</code> — 系统架构、模块划分、数据流设计</li><li><code>[工具]</code> — 依赖选择、库选型、第三方服务</li><li><code>[约定]</code> — 代码规范、命名约定、流程约定</li><li><code>[性能]</code> — 性能优化相关</li><li><code>[安全]</code> — 安全策略与措施</li></ul><p><strong>示例</strong>：</p><div class="language-markdown"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#E5C07B;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#61AFEF;--shiki-dark-text-decoration:inherit;">2026-07-03</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#61AFEF;--shiki-dark-text-decoration:inherit;">工具</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] 数据库选型 → SQLite | 单用户低并发，减少运维成本 | via:Codex</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#E5C07B;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#61AFEF;--shiki-dark-text-decoration:inherit;">2026-07-04</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#61AFEF;--shiki-dark-text-decoration:inherit;">架构</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] 放弃 Redis → 内存缓存 | 数据量 &lt; 100MB，Redis 运维开销 &gt; 收益 | via:WorkBuddy</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#E5C07B;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#61AFEF;--shiki-dark-text-decoration:inherit;">2026-07-05</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#61AFEF;--shiki-dark-text-decoration:inherit;">约定</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">] API 响应格式统一 → {code, data, msg} | 前端统一处理 | via:Cursor</span></span></code></pre></div><h3 id="working-todo-md-—-进度跟踪" tabindex="-1">working/todo.md — 进度跟踪 <a class="header-anchor" href="#working-todo-md-—-进度跟踪" aria-label="Permalink to “working/todo.md — 进度跟踪”">​</a></h3><p><strong>结构</strong>：进度总览表（阶段｜名称｜状态｜完成时间）+ 待办清单（复选框）。</p><p><strong>状态值</strong>：⬜ 未开始 | 🔄 进行中 | ✅ 已完成 | ⏸️ 暂缓</p><h3 id="working-plan-md-—-实施计划-可选" tabindex="-1">working/plan.md — 实施计划（可选） <a class="header-anchor" href="#working-plan-md-—-实施计划-可选" aria-label="Permalink to “working/plan.md — 实施计划（可选）”">​</a></h3><p><strong>创建时机</strong>：当前阶段需要 3+ 步骤时才创建。完成后归档到 <code>.memory/archive/</code> 或删除。</p><hr><h2 id="写入原则" tabindex="-1">写入原则 <a class="header-anchor" href="#写入原则" aria-label="Permalink to “写入原则”">​</a></h2><ol><li><strong>简洁具体</strong> — 不复制代码或对话，只记录要点和结论</li><li><strong>可检索</strong> — 使用清晰的标题和关键词；decisions 用分类标签</li><li><strong>可对比</strong> — 重要决策记录备选方案和理由</li><li><strong>有时效</strong> — 标注日期，过时信息及时更新</li><li><strong>不含敏感信息</strong> — 不存储密钥、凭证等</li><li><strong>标记来源</strong> — 使用 <code>via:来源</code> 标记写入者</li></ol><hr><h2 id="定期维护" tabindex="-1">定期维护 <a class="header-anchor" href="#定期维护" aria-label="Permalink to “定期维护”">​</a></h2><table tabindex="0"><thead><tr><th>周期</th><th>操作</th></tr></thead><tbody><tr><td><strong>每次会话结束</strong></td><td>更新 todo.md + 追加 decisions（如需要）</td></tr><tr><td><strong>每个阶段完成</strong></td><td>清理 todo.md 已完成条目，归档 plan.md</td></tr><tr><td><strong>每季度</strong></td><td>审查 decisions.md：超过 90 天且已固化到代码的决策 → 移到 <code>archive/decisions-YYYY-QX.md</code>；审查 AGENTS.md 技术栈和约定是否与代码一致</td></tr></tbody></table><hr><h2 id="何时需要创建-memory" tabindex="-1">何时需要创建 .memory <a class="header-anchor" href="#何时需要创建-memory" aria-label="Permalink to “何时需要创建 .memory”">​</a></h2><p><strong>需要创建</strong>：</p><ul><li>多文件迭代的项目（3+ 文件）</li><li>需要跨天/跨会话持续开发的</li><li>涉及技术决策和架构选择的</li><li>有明确开发阶段的</li></ul><p><strong>跳过</strong>：</p><ul><li>一次性脚本</li><li>单轮问答</li><li>不涉及文件修改的对话</li></ul><hr><h2 id="设计哲学" tabindex="-1">设计哲学 <a class="header-anchor" href="#设计哲学" aria-label="Permalink to “设计哲学”">​</a></h2><p>本系统采用<strong>项目级独立记忆</strong>，每个项目自带 <code>.memory/</code>，不依赖全局记忆层。理由：</p><ul><li>日常开发通常只需专注 1-2 个项目</li><li>项目级记忆随代码一起保留，不污染其他项目</li><li>无需维护跨项目的全局状态</li><li><code>.memory/</code> 目录可作为项目资产的一部分直接拷贝、打包、归档</li></ul><hr><h2 id="参考文档" tabindex="-1">参考文档 <a class="header-anchor" href="#参考文档" aria-label="Permalink to “参考文档”">​</a></h2><ul><li><code>references/constitution.md</code> — 详细设计规范，包含每个文件的字段意图和操作细则</li><li><code>references/maintenance.md</code> — 维护操作手册，存档策略和清理流程</li></ul>`,68)),s(a),s(e)])}const A=o(l,[["render",h]]);export{u as __pageData,A as default};
